#!/usr/bin/env python3
"""Install or update Claude Code from its npm platform package.

Rerun to update; --check reports without installing. On Termux this writes a
grun launcher at ~/.local/bin/claude whose `claude update` reruns this script.
"""
import sys

from _npm_native import Tool, main, q, shebang


def launcher(tool, lay, p):
    return f"""{shebang(p)}
# Generated by {tool.installer}; rerun it (or `claude update`) instead of editing.
# Claude Code ships no Android build, so this runs the linux-arm64 glibc build
# through Termux's glibc-runner. Its own updater cannot replace that, so it is
# disabled and `claude update` goes to the installer.
case "${{1-}}" in
	update|upgrade) shift; exec {q(tool.installer)} "$@" ;;
esac
export DISABLE_AUTOUPDATER=1
exec grun {q(lay.binary)} "$@"
"""


TOOL = Tool(
    name="claude",
    label="Claude Code",
    package="@anthropic-ai/claude-code",
    os_words={"linux": "linux", "darwin": "darwin", "windows": "win32"},
    installer="install_claude.py",
    launcher=launcher,
)

if __name__ == "__main__":
    sys.exit(main(TOOL))
